parts.text:
{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "A generator may accumulate as much as 55 gallons of non-acute hazardous waste and either 1 quart of liquid acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code or 1 kilogram (2.2 pounds) of solid acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code in containers at or near any point of generation where wastes initially accumulate which is under the control of the operator of the process generating the waste, without a permit or permit by rule and without complying with the requirements of Chapters 3745-50, 3745-54 to 3745-57 and 3745-205, 3745-65 to 3745-69 and 3745-256, 3745-266, and 3745-267 of the Administrative Code, provided that all of the conditions for exemption in rule 3745-52-15 of the Administrative Code are met.",
        "kind": "permission",
        "modality": "may",
        "references": [
          "rule 3745-51-31",
          "paragraph (E) of rule 3745-51-33",
          "Chapters 3745-50",
          "3745-54 to 3745-57",
          "3745-205",
          "3745-65 to 3745-69",
          "3745-256",
          "3745-266",
          "3745-267"
        ]
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "A generator may comply with the conditions for exemption in rule 3745-52-15 of the Administrative Code instead of complying with the conditions for exemption in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, except as required in paragraphs (A)(7) and (A)(8) of rule 3745-52-15.",
        "kind": "permission",
        "modality": "may",
        "references": [
          "paragraph (B) of rule 3745-52-16",
          "paragraph (A) of rule 3745-52-17",
          "paragraphs (A)(7) and (A)(8) of this rule"
        ]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "Under the satellite accumulation exemption conditions, if a container holding hazardous waste is not in good condition, or if the container begins to leak, the generator shall immediately transfer the hazardous waste from this container to a container that is in good condition and does not leak, or immediately transfer and manage the waste in a central accumulation area operated in compliance with paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "scope_quotes": ["F001"],
        "references": [
          "paragraph (B) of rule 3745-52-16",
          "paragraph (A) of rule 3745-52-17"
        ]
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "Under the satellite accumulation exemption conditions, the generator shall use a container made of or lined with materials that will not react with, and are otherwise compatible with, the hazardous waste to be accumulated, so that the ability of the container to contain the waste is not impaired.",
        "kind": "requirement",
        "modality": "must",
        "scope_quotes": ["F001"]
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "statement": "Under the satellite accumulation exemption conditions, incompatible wastes, or incompatible wastes and materials, shall not be placed in the same container, unless paragraph (B) of rule 3745-65-17 of the Administrative Code is complied with.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_quotes": ["F001"],
        "references": [
          "appendix to rule 3745-66-99",
          "paragraph (B) of rule 3745-65-17"
        ]
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "statement": "Under the satellite accumulation exemption conditions, hazardous waste shall not be placed in an unwashed container that previously held an incompatible waste or material, unless paragraph (B) of rule 3745-65-17 of the Administrative Code is complied with.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_quotes": ["F001"],
        "references": [
          "appendix to rule 3745-66-99",
          "paragraph (B) of rule 3745-65-17"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "Under the satellite accumulation exemption conditions, a container holding a hazardous waste that is incompatible with any waste or other materials accumulated nearby in other containers shall be separated from the other materials or protected from the incompatible waste or material by any practical means.",
        "kind": "requirement",
        "modality": "must",
        "scope_quotes": ["F001"]
      }
    },
    {
      "unit": "F008:F012",
      "unit_attributes": {
        "statement": "Under the satellite accumulation exemption conditions, a container holding hazardous waste shall be closed at all times during accumulation, except when adding, removing, or consolidating waste, or when temporary venting of a container is necessary either for the proper operation of equipment or to prevent dangerous situations, such as build-up of extreme pressure.",
        "kind": "requirement",
        "modality": "must",
        "scope_quotes": ["F001"]
      }
    },
    {
      "unit": "F013:F015",
      "unit_attributes": {
        "statement": "Under the satellite accumulation exemption conditions, a generator shall mark or label the generator's container with both the words 'Hazardous Waste' and an indication of the hazards of the contents.",
        "kind": "requirement",
        "modality": "must",
        "scope_quotes": ["F001"],
        "references": [
          "49 CFR Part 172 subpart E",
          "49 CFR Part 172 subpart F",
          "29 CFR 1910.1200",
          "national fire protection association code 704"
        ]
      }
    },
    {
      "unit": "F016:F021",
      "unit_attributes": {
        "statement": "A generator who accumulates either acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code or non-acute hazardous waste in excess of the amounts listed in paragraph (A) of rule 3745-52-15 at or near any point of generation shall, within three consecutive calendar days, comply with the applicable central accumulation area requirements in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, or remove the excess from the satellite accumulation area within three consecutive calendar days to a central accumulation area operated in accordance with the applicable requirements in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, an on-site permit by rule or permitted treatment, storage, or disposal facility, or an off-site designated facility.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "rule 3745-51-31",
          "paragraph (E) of rule 3745-51-33",
          "paragraph (A) of this rule",
          "paragraph (B) of rule 3745-52-16",
          "paragraph (A) of rule 3745-52-17"
        ]
      }
    },
    {
      "unit": "F022",
      "unit_attributes": {
        "statement": "During the three-consecutive-calendar-day period when excess hazardous waste is accumulated beyond the allowed amounts at or near a point of generation, the generator shall continue to comply with paragraphs (A)(1) to (A)(5) of rule 3745-52-15 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "scope_quotes": ["F016"],
        "references": ["paragraphs (A)(1) to (A)(5) of this rule"]
      }
    },
    {
      "unit": "F022",
      "unit_attributes": {
        "statement": "During the three-consecutive-calendar-day period when excess hazardous waste is accumulated beyond the allowed amounts at or near a point of generation, the generator shall mark or label the containers holding the excess accumulation of hazardous waste with the date the excess amount began accumulating.",
        "kind": "requirement",
        "modality": "must",
        "scope_quotes": ["F016"]
      }
    },
    {
      "unit": "F023",
      "unit_attributes": {
        "statement": "All satellite accumulation areas operated by a small quantity generator shall meet the preparedness and prevention requirements of paragraph (B)(8) of rule 3745-52-16 of the Administrative Code and emergency procedures of paragraph (B)(9) of rule 3745-52-16 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "references": [
          "paragraph (B)(8) of rule 3745-52-16",
          "paragraph (B)(9) of rule 3745-52-16"
        ]
      }
    },
    {
      "unit": "F024",
      "unit_attributes": {
        "statement": "All satellite accumulation areas operated by a large quantity generator shall meet the preparedness, prevention, and emergency procedures in rules 3745-52-250 to 3745-52-265 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "references": ["rules 3745-52-250 to 3745-52-265"]
      }
    },
    {
      "unit": "F026",
      "unit_attributes": {
        "statement": "For dates of non-regulatory government publications, publications of recognized organizations and associations, federal rules, and federal statutory provisions referenced in rule 3745-52-15, see rule 3745-50-11 of the Administrative Code titled 'Incorporated by reference.'",
        "kind": "statement",
        "modality": "not_stated",
        "references": ["rule 3745-50-11"]
      }
    }
  ]
}
